24	
25	const product = "CaseDock"
26	const resourceName = "tickets"
27	
28	// timeLayout 使用固定宽度的小数位，保证字符串按时间先后可比较。
29	const timeLayout = "2006-01-02T15:04:05.000000000Z07:00"
30	
31	// validSources / validPriorities 是页面与接口共用的合法选项。
32	var validSources = []string{"在线", "电话", "邮件"}
33	var validPriorities = []string{"低", "普通", "高", "紧急"}
34	
35	// ticketInput 是登记接口接收的字段，全部按文字处理。
36	type ticketInput struct {
37		Description    string `json:"description"`
38		ContactName    string `json:"contactName"`
39		ContactInfo    string `json:"contactInfo"`
40		Source         string `json:"source"`
41		Category       string `json:"category"`
42		Priority       string `json:"priority"`
43		AttachmentNote string `json:"attachmentNote"`
44		OrderNumber    string `json:"orderNumber"`
45		SubmitID       string `json:"submitId"`
46	}
47	
48	// unassigned 是登记后尚未分派时的负责人占位文字，不能作为负责人填写。
49	const unassigned = "未分派"
50	
51	// assignmentInput 是分派接口接收的字段，负责人按文字处理。
52	type assignmentInput struct {
53		Assignee    string `json:"assignee"`
54		OperationID string `json:"operationId"`
55	}
56	
57	// assignment 是一次负责人实际变化的分派记录。
58	type assignment struct {
59		From string `json:"from"`
60		To   string `json:"to"`
61		At   string `json:"at"`
62	}
63	
64	// ticket 是保存并返回的工单记录。
65	type ticket struct {
66		ID             string       `json:"id"`
67		Description    string       `json:"description"`
68		ContactName    string       `json:"contactName"`
69		ContactInfo    string       `json:"contactInfo"`
70		Source         string       `json:"source"`
71		Category       string       `json:"category"`
72		Priority       string       `json:"priority"`
73		AttachmentNote string       `json:"attachmentNote"`
74		OrderNumber    string       `json:"orderNumber"`
75		Status         string       `json:"status"`
76		Assignee       string       `json:"assignee"`
77		CreatedAt      string       `json:"createdAt"`
78		UpdatedAt      string       `json:"updatedAt"`
79		Assignments    []assignment `json:"assignments"`
80	}
81	
82	// storeFile 是磁盘上的持久化结构。submitIds 与 tickets 按位置一一对应。
83	type storeFile struct {
84		Seq       int      `json:"seq"`
85		Tickets   []ticket `json:"tickets"`
86		SubmitIDs []string `json:"submitIds"`
87		// AssignOperations 记录每张工单已成功的分派操作标识及其负责人：
88		// 工单编号 -> operationId -> 去除首尾空白后的负责人。
89		AssignOperations map[string]map[string]string `json:"assignOperations,omitempty"`
90	}
91	
92	// ticketStore 持久化工单与已成功的提交标识，所有方法并发安全。
93	type ticketStore struct {
94		mu        sync.Mutex
95		path      string
96		seq       int
97		tickets   []ticket
98		bySubmit  map[string]int               // submitId -> tickets 下标
99		assignOps map[string]map[string]string // 工单编号 -> operationId -> assignee
100	}
101	
102	func loadStore(path string) (*ticketStore, error) {
103		s := &ticketStore{path: path, tickets: []ticket{}, bySubmit: map[string]int{}, assignOps: map[string]map[string]string{}}
104		raw, err := os.ReadFile(path)
105		if err != nil {
106			return nil, err
107		}
108		var data storeFile
109		if err := json.Unmarshal(raw, &data); err != nil {
110			// 兼容旧版本的纯数组文件 []。
111			var legacy []ticket
112			if legacyErr := json.Unmarshal(raw, &legacy); legacyErr != nil {
113				return nil, err
114			}
115			data.Tickets = legacy
116		}
117		if data.Tickets != nil {
118			s.tickets = data.Tickets
119		}
120		s.seq = data.Seq
121		for i, t := range s.tickets {
122			// 编号是重启后不重复的最终依据；旧数据缺少 seq 时从编号恢复。
123			var n int
124			if _, scanErr := fmt.Sscanf(t.ID, "TKT-%d", &n); scanErr == nil && n > s.seq {
125				s.seq = n
126			}
127			if i < len(data.SubmitIDs) && data.SubmitIDs[i] != "" {
128				s.bySubmit[data.SubmitIDs[i]] = i
129			}
130		}
131		for id, ops := range data.AssignOperations {
132			if len(ops) > 0 {
133				s.assignOps[id] = ops
134			}
135		}
136		return s, nil
137	}
138	
139	// persistLocked 将当前数据原子写入磁盘，调用方须持有 s.mu。
140	func (s *ticketStore) persistLocked() error {
141		ids := make([]string, len(s.tickets))
142		for id, i := range s.bySubmit {
143			if i >= 0 && i < len(ids) {
144				ids[i] = id
145			}
146		}
147		data := storeFile{Seq: s.seq, Tickets: s.tickets, SubmitIDs: ids, AssignOperations: s.assignOps}
148		buf, err := json.MarshalIndent(data, "", "  ")
149		if err != nil {
150			return err
151		}
152		buf = append(buf, '\n')
153		tmp := s.path + ".tmp"
154		if err := os.WriteFile(tmp, buf, 0600); err != nil {
155			return err
156		}
157		return os.Rename(tmp, s.path)
158	}
159	
160	var errConflict = errors.New("submit id reused with different content")
161	
162	// create 校验后的数据登记为工单。同一提交标识、相同内容为幂等重放，
163	// 返回已有工单且 replay=true；同一标识不同内容返回 errConflict 且不改数据。
164	func (s *ticketStore) create(in ticketInput) (t ticket, replay bool, err error) {
165		s.mu.Lock()
166		defer s.mu.Unlock()
167		if idx, ok := s.bySubmit[in.SubmitID]; ok {
168			existing := s.tickets[idx]
169			if sameTicketContent(existing, in) {
170				return existing, true, nil
171			}
172			return ticket{}, false, errConflict
173		}
174		s.seq++
175		now := time.Now().Format(timeLayout)
176		t = ticket{
177			ID:             fmt.Sprintf("TKT-%06d", s.seq),
178			Description:    in.Description,
179			ContactName:    in.ContactName,
180			ContactInfo:    in.ContactInfo,
181			Source:         in.Source,
182			Category:       in.Category,
183			Priority:       in.Priority,
184			AttachmentNote: in.AttachmentNote,
185			OrderNumber:    in.OrderNumber,
186			Status:         "待处理",
187			Assignee:       unassigned,
188			CreatedAt:      now,
189			UpdatedAt:      now,
190		}
191		s.tickets = append(s.tickets, t)
192		s.bySubmit[in.SubmitID] = len(s.tickets) - 1
193		if err := s.persistLocked(); err != nil {
194			// 保存失败：回滚内存中的本次变更，登记不算完成。
195			delete(s.bySubmit, in.SubmitID)
196			s.tickets = s.tickets[:len(s.tickets)-1]
197			s.seq--
198			return ticket{}, false, err
199		}
200		return t, false, nil
201	}
202	
203	var errNotFound = errors.New("ticket not found")
204	var errAssignConflict = errors.New("operation id reused with a different assignee")
205	
206	// assign 将工单负责人分派或转交给 in.Assignee。changed 表示负责人是否实际变化。
207	// 同一工单内同一操作标识：提交相同负责人为幂等重放，返回当前工单且不做任何修改
208	// （即使工单后来已转交给别人，也不会被改回）；提交不同负责人返回 errAssignConflict。
209	// 负责人与当前相同视为成功但不追加记录、不刷新最近处理时间，操作标识仍会记录。
210	func (s *ticketStore) assign(id string, in assignmentInput) (t ticket, changed bool, err error) {
211		s.mu.Lock()
212		defer s.mu.Unlock()
213		idx := -1
214		for i, tk := range s.tickets {
215			if tk.ID == id {
216				idx = i
217				break
218			}
219		}
220		if idx == -1 {
221			return ticket{}, false, errNotFound
222		}
223		ops := s.assignOps[id]
224		if prev, ok := ops[in.OperationID]; ok {
225			if prev == in.Assignee {
226				// 幂等重放：返回当前工单，不修改负责人、时间或记录。
227				return s.tickets[idx], false, nil
228			}
229			return ticket{}, false, errAssignConflict
230		}
231		if ops == nil {
232			ops = map[string]string{}
233		}
234		ops[in.OperationID] = in.Assignee
235	
236		cur := s.tickets[idx]
237		if cur.Assignee == in.Assignee {
238			// 负责人未变化：只记录操作标识，不追加分派记录、不刷新最近处理时间。
239			s.assignOps[id] = ops
240			if err := s.persistLocked(); err != nil {
241				delete(ops, in.OperationID)
242				return ticket{}, false, err
243			}
244			return cur, false, nil
245		}
246	
247		now := time.Now().Format(timeLayout)
248		updated := cur
249		updated.Assignments = append(append([]assignment{}, cur.Assignments...), assignment{From: cur.Assignee, To: in.Assignee, At: now})
250		updated.Assignee = in.Assignee
251		updated.UpdatedAt = now
252		s.tickets[idx] = updated
253		s.assignOps[id] = ops
254		if err := s.persistLocked(); err != nil {
255			// 保存失败：回滚内存中的本次变更，分派不算完成。
256			delete(ops, in.OperationID)
257			s.tickets[idx] = cur
258			return ticket{}, false, err
259		}
260		return updated, true, nil
261	}
262	
263	// list 返回按创建时间从新到旧排列的工单副本。
264	func (s *ticketStore) list() []ticket {
265		s.mu.Lock()
266		defer s.mu.Unlock()
267		out := make([]ticket, len(s.tickets))
268		copy(out, s.tickets)
269		sort.SliceStable(out, func(i, j int) bool {
270			if out[i].CreatedAt != out[j].CreatedAt {
271				return out[i].CreatedAt > out[j].CreatedAt
272			}
273			return out[i].ID > out[j].ID
274		})
275		return out
276	}
277	
278	// sameTicketContent 按文字处理规则比较已有工单与本次提交（提交标识除外）。
279	func sameTicketContent(t ticket, in ticketInput) bool {
280		return t.Description == in.Description &&
281			t.ContactName == in.ContactName &&
282			t.ContactInfo == in.ContactInfo &&
283			t.Source == in.Source &&
284			t.Category == in.Category &&
285			t.Priority == in.Priority &&
286			t.AttachmentNote == in.AttachmentNote &&
287			t.OrderNumber == in.OrderNumber
288	}
289	
290	// validateInput 按页面与接口一致的规则校验，并对文字字段去除首尾空白。
291	// 描述与附件说明只去除整体首尾空白，正文内部换行保留。
292	func validateInput(in *ticketInput) error {
293		in.Description = strings.TrimSpace(in.Description)
294		in.ContactName = strings.TrimSpace(in.ContactName)
295		in.ContactInfo = strings.TrimSpace(in.ContactInfo)
296		in.Source = strings.TrimSpace(in.Source)
297		in.Category = strings.TrimSpace(in.Category)
298		in.Priority = strings.TrimSpace(in.Priority)
299		in.AttachmentNote = strings.TrimSpace(in.AttachmentNote)
300		// 联系方式与订单号始终是字符串，不做数字转换，前导零不会丢失。
301		in.OrderNumber = strings.TrimSpace(in.OrderNumber)
302		in.SubmitID = strings.TrimSpace(in.SubmitID)
303	
304		var missing []string
305		for _, f := range []struct{ name, value string }{
306			{"description", in.Description},
307			{"contactName", in.ContactName},
308			{"contactInfo", in.ContactInfo},
309			{"category", in.Category},
310			{"submitId", in.SubmitID},
311		} {
312			if f.value == "" {
313				missing = append(missing, f.name)
314			}
315		}
316		if len(missing) > 0 {
317			return fmt.Errorf("missing or empty required fields: %s", strings.Join(missing, ", "))
318		}
319		if !oneOf(in.Source, validSources) {
320			return fmt.Errorf("invalid source: %q; allowed: %s", in.Source, strings.Join(validSources, "/"))
321		}
322		if !oneOf(in.Priority, validPriorities) {
323			return fmt.Errorf("invalid priority: %q; allowed: %s", in.Priority, strings.Join(validPriorities, "/"))
324		}
325		return nil
326	}
327	
328	// validateAssignment 校验分派请求，并对文字字段去除首尾空白。
329	// 负责人去空白后必须有内容，且不能是占位文字“未分派”；操作标识必须非空。
330	func validateAssignment(in *assignmentInput) error {
331		in.Assignee = strings.TrimSpace(in.Assignee)
332		in.OperationID = strings.TrimSpace(in.OperationID)
333		if in.Assignee == "" {
334			return errors.New("missing or empty required field: assignee")
335		}
336		if in.Assignee == unassigned {
337			return fmt.Errorf("invalid assignee: %q is reserved and cannot be used", unassigned)
338		}
339		if in.OperationID == "" {
340			return errors.New("missing or empty required field: operationId")
341		}
342		return nil
343	}
344	
345	func oneOf(v string, allowed []string) bool {
346		for _, a := range allowed {
347			if v == a {
348				return true
349			}
350		}
351		return false
352	}
353	
354	func newSubmitID() string {
355		b := make([]byte, 16)
356		if _, err := rand.Read(b); err != nil {
357			// rand 失败极不可能发生；退回纳秒时间戳仍能给出非空标识。
358			return fmt.Sprintf("sub-%d", time.Now().UnixNano())
359		}
360		return "sub-" + hex.EncodeToString(b)
361	}
362	
363	func respond(w http.ResponseWriter, status int, allow string, value any) {
364		w.Header().Set("Content-Type", "application/json; charset=utf-8")
365		if allow != "" {
366			w.Header().Set("Allow", allow)
367		}
368		w.WriteHeader(status)
369		_ = json.NewEncoder(w).Encode(value)
370	}
371	
372	func run() error {
373		if len(os.Args) < 2 {
374			printHelp()
375			return errors.New("expected serve or --help")
376		}
377		if os.Args[1] == "--help" || os.Args[1] == "-h" {
378			printHelp()
379			return nil
380		}
381		if os.Args[1] != "serve" {
382			return errors.New("expected serve or --help")
383		}
384		args := flag.NewFlagSet("case-dock serve", flag.ContinueOnError)
385		args.SetOutput(os.Stdout)
386		host := args.String("host", "127.0.0.1", "address to bind")
387		port := args.Int("port", 8080, "port to bind; 0 selects an available port")
388		data := args.String("data-dir", "data", "directory for local records")
389		if err := args.Parse(os.Args[2:]); errors.Is(err, flag.ErrHelp) {
390			return nil
391		} else if err != nil {
392			return err
393		}
394		if args.NArg() != 0 {
395			return errors.New("unexpected positional argument")
396		}
397		if *port < 0 || *port > 65535 {
398			return errors.New("port must be between 0 and 65535")
399		}
400		if err := os.MkdirAll(*data, 0700); err != nil {
401			return err
402		}
403		dataFile := filepath.Join(*data, "tickets.json")
404		if _, err := os.Stat(dataFile); errors.Is(err, os.ErrNotExist) {
405			buf, err := json.MarshalIndent(storeFile{Seq: 0, Tickets: []ticket{}, SubmitIDs: []string{}}, "", "  ")
406			if err != nil {
407				return err
408			}
409			buf = append(buf, '\n')
410			if err := os.WriteFile(dataFile, buf, 0600); err != nil {
411				return err
412			}
413		} else if err != nil {
414			return err
415		}
416		store, err := loadStore(dataFile)
417		if err != nil {
418			return fmt.Errorf("load %s: %w", dataFile, err)
419		}
420	
421		mux := http.NewServeMux()
422		mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
423			if r.URL.Path != "/" {
424				respond(w, http.StatusNotFound, "", map[string]string{"error": "not found"})
425				return
426			}
427			if r.Method != http.MethodGet {
428				respond(w, http.StatusMethodNotAllowed, "GET", map[string]string{"error": "method not allowed"})
429				return
430			}
431			w.Header().Set("Content-Type", "text/html; charset=utf-8")
432			_, _ = io.WriteString(w, page)
433		})
434		mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
435			if r.Method != http.MethodGet {
436				respond(w, http.StatusMethodNotAllowed, "GET", map[string]string{"error": "method not allowed"})
437				return
438			}
439			respond(w, http.StatusOK, "", map[string]string{"status": "ok", "product": product})
440		})
441		mux.HandleFunc("/api/tickets", func(w http.ResponseWriter, r *http.Request) {
442			switch r.Method {
443			case http.MethodGet:
444				tickets := store.list()
445				respond(w, http.StatusOK, "", map[string]any{resourceName: tickets})
446			case http.MethodPost:
447				body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
448				if err != nil {
449					respond(w, http.StatusBadRequest, "", map[string]string{"error": "unable to read request body"})
450					return
451				}
452				dec := json.NewDecoder(bytes.NewReader(body))
453				var in ticketInput
454				if decErr := dec.Decode(&in); decErr != nil {
455					if errors.Is(decErr, io.EOF) {
456						decErr = errors.New("request body is empty")
457					}
458					respond(w, http.StatusBadRequest, "", map[string]string{"error": "invalid JSON: " + decErr.Error()})
459					return
460				}
461				var tail json.RawMessage
462				if decErr := dec.Decode(&tail); !errors.Is(decErr, io.EOF) {
463					respond(w, http.StatusBadRequest, "", map[string]string{"error": "invalid JSON: trailing data after the JSON object"})
464					return
465				}
466				if err := validateInput(&in); err != nil {
467					respond(w, http.StatusBadRequest, "", map[string]string{"error": err.Error()})
468					return
469				}
470				t, replay, err := store.create(in)
471				if errors.Is(err, errConflict) {
472					respond(w, http.StatusConflict, "", map[string]string{"error": "submit id was already used with different content"})
473					return
474				}
475				if err != nil {
476					respond(w, http.StatusInternalServerError, "", map[string]string{"error": "unable to save ticket"})
477					return
478				}
479				status := http.StatusCreated
480				if replay {
481					status = http.StatusOK
482				}
483				respond(w, status, "", t)
484			default:
485				respond(w, http.StatusMethodNotAllowed, "GET, POST", map[string]string{"error": "method not allowed"})
486			}
487		})
488		mux.HandleFunc("/api/tickets/{id}/assignment", func(w http.ResponseWriter, r *http.Request) {
489			if r.Method != http.MethodPost {
490				respond(w, http.StatusMethodNotAllowed, "POST", map[string]string{"error": "method not allowed"})
491				return
492			}
493			id := r.PathValue("id")
494			body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
495			if err != nil {
496				respond(w, http.StatusBadRequest, "", map[string]string{"error": "unable to read request body"})
497				return
498			}
499			dec := json.NewDecoder(bytes.NewReader(body))
500			var in assignmentInput
501			if decErr := dec.Decode(&in); decErr != nil {
502				if errors.Is(decErr, io.EOF) {
503					decErr = errors.New("request body is empty")
504				}
505				respond(w, http.StatusBadRequest, "", map[string]string{"error": "invalid JSON: " + decErr.Error()})
506				return
507			}
508			var tail json.RawMessage
509			if decErr := dec.Decode(&tail); !errors.Is(decErr, io.EOF) {
510				respond(w, http.StatusBadRequest, "", map[string]string{"error": "invalid JSON: trailing data after the JSON object"})
511				return
512			}
513			if err := validateAssignment(&in); err != nil {
514				respond(w, http.StatusBadRequest, "", map[string]string{"error": err.Error()})
515				return
516			}
517			t, changed, err := store.assign(id, in)
518			if errors.Is(err, errNotFound) {
519				respond(w, http.StatusNotFound, "", map[string]string{"error": "ticket not found: " + id})
520				return
521			}
522			if errors.Is(err, errAssignConflict) {
523				respond(w, http.StatusConflict, "", map[string]string{"error": "operation id was already used with a different assignee"})
524				return
525			}
526			if err != nil {
527				respond(w, http.StatusInternalServerError, "", map[string]string{"error": "unable to save assignment"})
528				return
529			}
530			respond(w, http.StatusOK, "", map[string]any{"ticket": t, "changed": changed})
531		})
532	
533		server := &http.Server{
534			Handler:           mux,
535			ReadHeaderTimeout: 5 * time.Second,
536		}
537		listener, err := net.Listen("tcp", net.JoinHostPort(*host, fmt.Sprint(*port)))
538		if err != nil {
539			return err
540		}
541		fmt.Printf("%s listening on http://%s\n", product, listener.Addr().String())
542		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
543		defer stop()
544		failures := make(chan error, 1)
545		go func() { failures <- server.Serve(listener) }()
546		select {
547		case err := <-failures:
548			if !errors.Is(err, http.ErrServerClosed) {
549				return err
550			}
551		case <-ctx.Done():
552			shutdown, cancel := context.WithTimeout(context.Background(), 3*time.Second)
553			defer cancel()
554			if err := server.Shutdown(shutdown); err != nil {
555				return err
556			}
557		}
558		return nil
559	}
