// 从 page.go 提取真实的 loadTickets 函数，在桩环境下模拟竞态：
// 列表读取始于分派之前，旧响应在分派成功后到达，已确认结果不得被回退。
const fs = require("fs");
const src = fs.readFileSync("/opt/gsb-production/workspaces/sl-chen/prod-14/B/task008/page.go", "utf8");

const start = src.indexOf("  function loadTickets(){");
const end = src.indexOf("\n  loadTickets();", start);
if (start === -1 || end === -1) { console.error("extract failed"); process.exit(1); }
const fnSrc = src.slice(start, end);

// ---- 桩环境 ----
let loaded = [];
let confirmed = {};
let rendered = null;
const listArea = {
  innerHTML: "",
  insertAdjacentHTML(pos, html) { this.innerHTML += html; },
};
function renderList() { rendered = loaded.map(t => t.id + ":" + t.assignee + "@" + t.updatedAt); }
function escapeHtml(s) { return String(s); }

// fetch 桩：GET /api/tickets 返回可延迟的响应
let pendingGet = [];
function fetch(url) {
  return new Promise((resolve) => pendingGet.push(resolve));
}

eval(fnSrc);

const oldA = { id: "TKT-000001", assignee: "未分派", updatedAt: "2026-10-03T10:00:00.000000000Z", createdAt: "2026-10-03T10:00:00.000000000Z", assignments: [] };
const newA = { id: "TKT-000001", assignee: "李四", updatedAt: "2026-10-03T10:05:00.000000000Z", createdAt: "2026-10-03T10:00:00.000000000Z", assignments: [{ from: "未分派", to: "李四", at: "2026-10-03T10:05:00.000000000Z" }] };
const newB = { id: "TKT-000002", assignee: "未分派", updatedAt: "2026-10-03T10:02:00.000000000Z", createdAt: "2026-10-03T10:02:00.000000000Z", assignments: [] };

async function main() {
  // 初始加载：列表里只有分派前的工单 A
  const p0 = loadTickets();
  pendingGet.shift()({ ok: true, json: async () => ({ tickets: [oldA] }) });
  await p0;
  console.assert(loaded.length === 1 && loaded[0].assignee === "未分派", "initial load");

  // 登记工单 B 成功 → 触发 loadTickets（响应慢，尚未返回）
  const p1 = loadTickets();
  // 等待期间用户把 A 分派给李四，接口确认成功（模拟 page.go 中的成功回调）
  confirmed[newA.id] = newA;
  for (let i = 0; i < loaded.length; i++) { if (loaded[i].id === newA.id) { loaded[i] = newA; break; } }
  renderList();
  console.assert(loaded[0].assignee === "李四", "list shows new assignee after assign");

  // 旧列表响应到达：内容始于分派前（A 仍是旧值），但包含新登记的 B
  pendingGet.shift()({ ok: true, json: async () => ({ tickets: [newB, oldA] }) });
  await p1;

  const a = loaded.find(t => t.id === "TKT-000001");
  const b = loaded.find(t => t.id === "TKT-000002");
  console.assert(a && a.assignee === "李四", "FAIL: assignee reverted");
  console.assert(a.updatedAt === "2026-10-03T10:05:00.000000000Z", "FAIL: updatedAt reverted");
  console.assert(a.assignments.length === 1 && a.assignments[0].to === "李四", "FAIL: assignment record lost");
  console.assert(b, "FAIL: newly registered ticket B missing");
  console.assert(loaded[0].id === "TKT-000002" && loaded[1].id === "TKT-000001", "FAIL: order not newest-first");

  // 下一次读取追平（服务端返回已含新负责人）：确认记录被清理，列表保持新值
  const p2 = loadTickets();
  pendingGet.shift()({ ok: true, json: async () => ({ tickets: [newB, newA] }) });
  await p2;
  console.assert(Object.keys(confirmed).length === 0, "FAIL: confirmed not cleaned up");
  console.assert(loaded.find(t => t.id === "TKT-000001").assignee === "李四", "FAIL: value changed after catch-up");

  // 读取失败：保留已显示内容与已确认结果
  const p3 = loadTickets();
  pendingGet.shift()({ ok: false, status: 500 });
  await p3;
  console.assert(loaded.length === 2 && loaded[1].assignee === "李四", "FAIL: list lost on error");
  console.assert(listArea.innerHTML.includes("刷新失败"), "FAIL: error notice missing");

  console.log("all assertions passed");
  console.log("rendered:", rendered);
}
main().catch(e => { console.error(e); process.exit(1); });

